diff --git a/src/core/project.ts b/src/core/project.ts
index 76d1577..e8e7989 100644
--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -7,11 +7,24 @@ export interface Record {
 }

 export const project = (records: readonly Record[]): string => {
+  const seen = new Set<string>();
   const lines: string[] = [];
+
+  const normalize = (s: string): string =>
+    s.toLowerCase().replace(/[^\w\s]/g, '').replace(/\s+/g, ' ').trim();
+
+  const addIfNew = (type: string, entry: string) => {
+    const key = `${type}:${normalize(entry)}`;
+    if (!seen.has(key)) {
+      seen.add(key);
+      lines.push(`- ${type}: ${entry}`);
+    }
+  };
+
   for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
+    for (const entry of record.ruledOut) addIfNew('ruled out', entry);
+    for (const limit of record.limits) addIfNew('limit', entry);
+    for (const warn of record.warns) addIfNew('warn', entry);
   }
   return lines.join("\n");
 };
